<?php
namespace Sellio\Connector;
defined( 'ABSPATH' ) || exit;
final class Client {
	private static function url( $path ) { $s = Settings::all(); $base = untrailingslashit( $s['api_base_url'] ); $u = wp_parse_url( $base ); $localhost = in_array( $u['host'] ?? '', array( 'localhost', '127.0.0.1', '::1' ), true ); if ( ! $u || empty( $u['host'] ) || ( 'https' !== ( $u['scheme'] ?? '' ) && ! ( $localhost && defined( 'SELLIO_CONNECTOR_ALLOW_INSECURE_LOCALHOST' ) && SELLIO_CONNECTOR_ALLOW_INSECURE_LOCALHOST ) ) ) { return new \WP_Error( 'sellio_url', __( 'Adres Sellio musi używać HTTPS (HTTP localhost wymaga stałej developerskiej).', 'sellio-connector' ) ); } return $base . $path; }
	private static function request( $method, $path, $body = null, $event = null ) { $url = self::url( $path ); if ( is_wp_error( $url ) ) { return $url; } $s = Settings::all(); $headers = array( 'Authorization' => 'Bearer ' . Settings::token(), 'X-Sellio-Store-Id' => $s['store_id'], 'Accept' => 'application/json' ); if ( $event ) { $headers['Idempotency-Key'] = $event; } if ( null !== $body ) { $headers['Content-Type'] = 'application/json'; } return wp_remote_request( $url, array( 'method' => $method, 'headers' => $headers, 'body' => null === $body ? null : wp_json_encode( $body ), 'timeout' => 15, 'redirection' => 0, 'sslverify' => true ) ); }
	public static function check() { $r = self::request( 'GET', '/v1/connector/connection' ); if ( is_wp_error( $r ) ) { return $r; } $code = wp_remote_retrieve_response_code( $r ); $data = json_decode( wp_remote_retrieve_body( $r ), true ); $s = Settings::all(); if ( 200 !== $code || ! is_array( $data ) || 'sellio' !== ( $data['service'] ?? '' ) || '1' !== (string) ( $data['api_version'] ?? '' ) || $s['store_id'] !== ( $data['store_id'] ?? '' ) || 'connected' !== ( $data['status'] ?? '' ) ) { return new \WP_Error( 'sellio_connection', __( 'Odpowiedź Sellio nie spełnia kontraktu połączenia.', 'sellio-connector' ), array( 'status' => $code ) ); } return true; }
	public static function send( $row ) { $payload = json_decode( $row->payload, true ); $r = self::request( 'POST', '/v1/connector/events', $payload, $row->event_id ); if ( is_wp_error( $r ) ) { return array( 'ok' => false, 'retry' => true, 'error' => $r->get_error_message(), 'code' => 0 ); } $code = wp_remote_retrieve_response_code( $r ); $data = json_decode( wp_remote_retrieve_body( $r ), true ); if ( in_array( $code, array( 200, 202 ), true ) && is_array( $data ) && true === ( $data['accepted'] ?? false ) && $row->event_id === ( $data['event_id'] ?? '' ) ) { return array( 'ok' => true, 'code' => $code ); } return array( 'ok' => false, 'retry' => ( 0 === $code || 408 === $code || 429 === $code || $code >= 500 ), 'error' => 'HTTP ' . $code, 'code' => $code, 'retry_after' => (int) wp_remote_retrieve_header( $r, 'retry-after' ) ); }
}
